package bo.edu.umss.mercado.statistics;

import bo.edu.umss.mercado.data.CanonicalJson;
import java.net.*;
import java.net.http.*;
import java.time.Duration;
import java.util.*;
import org.springframework.stereotype.Service;

/** Solo términos escritos/seleccionados por ADMIN; nunca consulta al cargar Resultados. */
@Service
public class WikidataTerms {
    public static class RateLimited extends IllegalStateException {private final int seconds;public RateLimited(int seconds){super("Wikidata limitó las consultas (HTTP 429). Reintenta dentro de "+seconds+" segundos.");this.seconds=seconds;}public int seconds(){return seconds;}}
    static class RequestGate {private long next,blocked; synchronized void check(long now){if(now<blocked)throw new RateLimited((int)Math.max(1,(blocked-now+999)/1000));}synchronized long delay(long now){check(now);long delay=Math.max(0,next-now);if(delay>5000)throw new RateLimited(5);next=now+delay+1200;return delay;}synchronized void throttle(long now,int seconds){blocked=Math.max(blocked,now+seconds*1000L);}}
    private final RequestGate gate=new RequestGate();
    private final HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).followRedirects(HttpClient.Redirect.NEVER).build();
    static URI endpoint(String query){return URI.create("https://www.wikidata.org/w/api.php?format=json&"+query.replace("|","%7C"));}
    private Map<?,?> get(String query){try{long delay=gate.delay(System.currentTimeMillis());if(delay>0)Thread.sleep(delay);gate.check(System.currentTimeMillis());var request=HttpRequest.newBuilder(endpoint(query)).timeout(Duration.ofSeconds(10)).header("User-Agent","UMSS-Survey-TermReview/1.0 (manual administrative lookup)").GET().build();var response=client.send(request,HttpResponse.BodyHandlers.ofInputStream());try(var body=response.body()){if(response.statusCode()==429){int seconds=retrySeconds(response.headers().firstValue("Retry-After").orElse("60"));gate.throttle(System.currentTimeMillis(),seconds);throw new RateLimited(seconds);}if(response.statusCode()!=200)throw new IllegalStateException("Wikidata respondió HTTP "+response.statusCode()+". Vuelve a intentar después.");byte[] bytes=body.readNBytes(262145);if(bytes.length>262144)throw new IllegalStateException("La consulta devolvió demasiados datos.");return CanonicalJson.read(new String(bytes,java.nio.charset.StandardCharsets.UTF_8),Map.class);}}catch(InterruptedException ex){Thread.currentThread().interrupt();throw new IllegalStateException("Consulta interrumpida.");}catch(java.net.http.HttpTimeoutException ex){throw new IllegalStateException("Wikidata tardó demasiado en responder. El término queda pendiente.");}catch(java.io.IOException ex){throw new IllegalStateException("No se pudo conectar con Wikidata. La edición local sigue disponible.");}}
    static int retrySeconds(String value){try{return Math.max(1,Math.min(300,Integer.parseInt(value)));}catch(NumberFormatException ex){try{return (int)Math.max(1,Math.min(300,Duration.between(java.time.ZonedDateTime.now(java.time.ZoneOffset.UTC),java.time.ZonedDateTime.parse(value,java.time.format.DateTimeFormatter.RFC_1123_DATE_TIME)).getSeconds()));}catch(java.time.DateTimeException ignored){return 60;}}}
    public List<Map<String,Object>> search(String term){if(term==null||term.isBlank()||term.length()>100||term.contains("@")||term.matches(".*\\d{6,}.*"))throw new IllegalArgumentException("Consulta un término de hasta cien caracteres, sin contactos ni identificadores.");var payload=get("action=wbsearchentities&language=es&uselang=es&limit=5&search="+URLEncoder.encode(term,java.nio.charset.StandardCharsets.UTF_8));var result=new ArrayList<Map<String,Object>>();if(payload.get("search") instanceof List<?> list)for(Object raw:list){var item=(Map<?,?>)raw;String id=Objects.toString(item.get("id"),"");if(id.matches("Q[0-9]+"))result.add(Map.of("id",id,"label",Objects.toString(item.get("label"),id),"description",Objects.toString(item.get("description"),""),"matched",item.get("match") instanceof Map<?,?> match?Objects.toString(match.get("text"),""):"","url","https://www.wikidata.org/wiki/"+id));}return result;}
    public Map<String,Object> aliases(String id){if(!id.matches("Q[0-9]{1,12}"))throw new IllegalArgumentException("Concepto de Wikidata no válido.");var payload=get("action=wbgetentities&props=labels|aliases&languages=es|en&ids="+id);var entities=(Map<?,?>)payload.get("entities");if(entities==null||!(entities.get(id) instanceof Map<?,?> entity))throw new IllegalStateException("No se encontró ese concepto.");var names=new LinkedHashSet<String>();for(String field:List.of("labels","aliases"))if(entity.get(field) instanceof Map<?,?> languages)for(Object raw:languages.values()){var entries=raw instanceof List<?> l?l:List.of(raw);for(Object entry:entries)if(entry instanceof Map<?,?> value){String text=Objects.toString(value.get("value"),"");if(!text.isBlank()&&text.length()<=100)names.add(text);}}return Map.of("id",id,"url","https://www.wikidata.org/wiki/"+id,"aliases",names.stream().limit(20).toList());}
}
